package com.example.rokidkeyboardbridge;
import org.json.*;import java.util.*;
/** Bounded in-memory numeric samples only. No destination, text, location or credentials. */
public final class NavigationSmoothMetrics {
 private final Map<String,ArrayDeque<Long>> samples=new LinkedHashMap<>();private final Map<String,Long> counters=new LinkedHashMap<>();
 public synchronized void sample(String kind,long nanos){if(!kind.matches("actionFrame|searchTotal|searchProvider|uiWork|uiQueue|pollGap|speechWait|packetBuild|packetSerialize|bridgeRoundTrip|phoneBuild|locationAgeAtPhone|receiveToFrame|packetProcess|fixAgeLower|fixAgeUpper|geometryEncode")||nanos<0||nanos>600000000000L)return;ArrayDeque<Long> values=samples.get(kind);if(values==null){values=new ArrayDeque<>();samples.put(kind,values);}if(values.size()>=120)values.removeFirst();values.addLast(nanos);}
 public void mark(String kind,long start){sample(kind,System.nanoTime()-start);}
 public synchronized void count(String kind){if(!kind.matches("searchDiscarded|drawSkipped|poseSkipped|refreshCoalesced|cueSuppressed|reconnect|searchCancelled"))return;counters.put(kind,counters.getOrDefault(kind,0L)+1);}
 public synchronized JSONObject snapshot()throws Exception{JSONObject out=new JSONObject(),rows=new JSONObject();for(Map.Entry<String,ArrayDeque<Long>> entry:samples.entrySet()){ArrayList<Long> sorted=new ArrayList<>(entry.getValue());Collections.sort(sorted);int n=sorted.size();if(n>0)rows.put(entry.getKey(),new JSONObject().put("count",n).put("p50Ms",sorted.get((n-1)/2)/1000000.0).put("p95Ms",sorted.get(Math.max(0,(int)Math.ceil(n*.95)-1))/1000000.0).put("maxMs",sorted.get(n-1)/1000000.0));}out.put("samples",rows).put("counts",new JSONObject(counters)).put("scope","process-local last 120 numeric samples; frame callback and speech dispatch, not display completion or audible onset");return out;}
 public static String text(JSONObject record){String[] keys={"actionFrame","searchTotal","searchProvider","uiWork","uiQueue","pollGap","speechWait","packetBuild","packetSerialize","bridgeRoundTrip","phoneBuild","locationAgeAtPhone","receiveToFrame","packetProcess","fixAgeLower","fixAgeUpper","geometryEncode"},labels={"操作受付→次の描画機会","候補・設定の確認全体","経路サービスへの問い合わせ","画面の更新処理","画面更新の順番待ち","ナビ情報の受信間隔","音声の送信待ち","案内パケットの作成","案内パケットの文字列化","スマホへの問い合わせ往復","スマホ側の案内作成","スマホ送信時の位置情報の経過時間","メガネ受信→次の描画機会","メガネの受信内容の処理","描画機会での位置情報の経過時間・下限","描画機会での位置情報の経過時間・上限","経路線の変更確認・送信準備"};StringBuilder out=new StringBuilder("今回の起動中・各項目は直近120件まで。\n");JSONObject samples=record.optJSONObject("samples");for(int i=0;i<keys.length;i++){JSONObject row=samples==null?null:samples.optJSONObject(keys[i]);out.append(labels[i]).append("：");if(row==null)out.append("未計測\n");else out.append(String.format(java.util.Locale.JAPAN,"中央値 %.1fms／95%%点 %.1fms（%d件）\n",row.optDouble("p50Ms"),row.optDouble("p95Ms"),row.optInt("count")));}JSONObject counts=record.optJSONObject("counts");if(counts!=null)out.append("\n同じ表示の更新省略：").append(counts.optLong("drawSkipped")).append("回\n同じ位置の計算省略：").append(counts.optLong("poseSkipped")).append("回\n");return out.toString();}
 public void show(android.app.Activity host){try{new android.app.AlertDialog.Builder(host).setTitle("ナビの応答時間（今回の起動中）").setMessage(text(snapshot())+"\n未計測は0msという意味ではありません。描画完了や実際に音が出るまでの時間ではなく、同じ操作条件での比較が必要です。").setPositiveButton("閉じる",null).show();}catch(Exception ignored){}}
}
